const fs = require('fs');
const path = require('path');
const Module = require('module');

// svelte2tsx and its dependencies come from the bundled Svelte language server
const dependencyRoot = path.resolve(__dirname, '../../../svelte-language-server/bin/node_modules');

function addNodePaths(directories) {
  const nodePath = process.env.NODE_PATH ? process.env.NODE_PATH.split(path.delimiter) : [];
  const added = directories.filter(directory => !nodePath.includes(directory));
  if (added.length === 0) return;
  process.env.NODE_PATH = [...added, ...nodePath].join(path.delimiter);
  Module._initPaths();
}

function getNodeModulesUpwards(directory) {
  const result = [];
  for (let current = path.resolve(directory); ; current = path.dirname(current)) {
    result.push(path.join(current, 'node_modules'));
    if (path.dirname(current) === current) return result;
  }
}

function isInDependencyRoot(file) {
  const roots = [dependencyRoot];
  try {
    roots.push(fs.realpathSync(dependencyRoot));
  }
  catch {
  }
  return roots.some(root => file.startsWith(root + path.sep));
}

// svelte2tsx requires `typescript` when it loads. Give it the TypeScript of this service,
// because the bundled TypeScript of the IDE is not a `typescript` package that Node.js can find.
let typescriptFile;

function useServiceTypeScript(typescript) {
  if (typescriptFile || !typescript.sys) return;
  typescriptFile = typescript.sys.getExecutingFilePath();
  const resolveFilename = Module._resolveFilename;
  Module._resolveFilename = function (request, parent, ...rest) {
    if (request === 'typescript' && parent && parent.filename && isInDependencyRoot(parent.filename)) {
      return typescriptFile;
    }
    return resolveFilename.call(this, request, parent, ...rest);
  };
}

// svelte2tsx also requires `svelte/compiler` when it loads, and this bundle has no node_modules of its own.
// Thus load the plugin for the first project, and resolve `svelte` from that project.
module.exports = function init(modules) {
  useServiceTypeScript(modules.typescript);
  let plugin;
  let pendingConfig;

  function load(projectDirectory) {
    if (!plugin) {
      addNodePaths([dependencyRoot, ...getNodeModulesUpwards(projectDirectory)]);
      plugin = require('./dist/src/index.js')(modules);
      if (pendingConfig !== undefined) plugin.onConfigurationChanged(pendingConfig);
    }
    return plugin;
  }

  return {
    create: info => load(info.project.getCurrentDirectory()).create(info),
    getExternalFiles: (project, updateLevel) => load(project.getCurrentDirectory()).getExternalFiles(project, updateLevel),
    onConfigurationChanged: config => {
      if (plugin) plugin.onConfigurationChanged(config);
      else pendingConfig = config;
    },
  };
};
